tring['empty'] . "</p>\n";  } else {    echo "<table cellpadding=\"2\" cellspacing=\"0\" border=\"0\" style=\"font-size:100%; border-collapse:collapse; border:1px solid #6B82B2\">\n";    echo "<tr style=\"text-align:center; border-collapse:collapse; border-top: 1px solid #6B82B2; border-bottom:1px solid #6B82B2; border-left:1px solid #6B82B2; background-image:url(../search_bar_background.png); background-repeat:repeat-x; height:23px; color:white; font-weight:bold\">\n";    echo "<td>&nbsp;</td><td>{$string['title']}</td><td>{$string['content']}</td><td>{$string['access']}</td><td>{$string['deleted']}</td></tr>\n";        while ($result->fetch()) {      if ($body == '') $body = '&nbsp;';      echo "<tr><td><a href=\"" . $_SERVER['PHP_SELF'] . "?id=$id\"><img src=\"../../artwork/restore.png\" width=\"16\" height=\"16\" border=\"0\" alt=\"" . $string['restore'] . "\" /></a></td><td><nobr>$title</nobr></td><td>$body</td><td><nobr>$deleted</nobr></td></tr>\n";    }    echo "</table>\n";  }    $mysqli->close();?></body></html>